dashboard.definition:
{
  "title": "HEC Token Performance",
  "description": "HTTP Event Collector throughput per token with 1-hour rolling-window silence detection.",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-4h@h,now"
      }
    }
  },
  "dataSources": {
    "ds_hec_time": {
      "type": "ds.search",
      "name": "HEC events by token",
      "options": {
        "query": "search `exec_health_hec_metrics`\n| `exec_health_hec_normalize`\n| lookup hec_token_map token OUTPUT token_name\n| eval token_label=coalesce(token_name, token)\n| timechart span=5m sum(hec_events) as events by token_label",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_hec_state": {
      "type": "ds.search",
      "name": "HEC token state",
      "options": {
        "query": "search `exec_health_hec_metrics` earliest=-2h@m latest=-1m@m\n| `exec_health_hec_normalize`\n| timechart span=1m limit=0 useother=f sum(hec_events) as events by token\n| fillnull value=0\n| untable _time token events\n| eval minutes_ago=round((relative_time(now(), \"-1m@m\")-_time)/60, 0)\n| eval window=case(minutes_ago>=1 AND minutes_ago<=`exec_health_hec_silence_min`, \"recent\", minutes_ago>`exec_health_hec_silence_min` AND minutes_ago<=`exec_health_hec_silence_min`+60, \"baseline\")\n| stats sum(eval(if(window=\"recent\", events, 0))) as recent_events, sum(eval(if(window=\"baseline\", events, 0))) as baseline_events, count(eval(window=\"recent\" AND events=0)) as silent_minutes by token\n| eval baseline_eps=round(baseline_events/3600, 2), recent_eps=round(recent_events/(60*`exec_health_hec_silence_min`), 2)\n| lookup hec_token_map token OUTPUT token_name, owner\n| eval token_label=coalesce(token_name, token), owner=coalesce(owner, \"unmapped\")\n| eval hec_state=case(\n    baseline_eps >= `exec_health_hec_baseline_eps` AND recent_events=0, \"ALERT\",\n    baseline_eps >= 10 AND recent_events=0, \"YELLOW\",\n    1=1, \"OK\")\n| eval _color_rank=case(hec_state=\"ALERT\", 1, hec_state=\"YELLOW\", 2, 1=1, 3)\n| table token, token_label, owner, recent_events, recent_eps, baseline_eps, silent_minutes, hec_state, _color_rank\n| sort _color_rank, token_label",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-2h@m",
          "latest": "-1m@m"
        }
      }
    },
    "ds_hec_totals": {
      "type": "ds.search",
      "name": "HEC totals",
      "options": {
        "query": "search `exec_health_hec_metrics`\n| `exec_health_hec_normalize`\n| stats sum(hec_events) as events, dc(token) as tokens, sum(hec_bytes) as bytes\n| fillnull value=0 events, tokens, bytes\n| eval events_per_sec=round(events/3600, 1)\n| eval gb=round(bytes/1024/1024/1024, 3)",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-1h",
          "latest": "now"
        }
      }
    },
    "ds_hec_handler": {
      "type": "ds.search",
      "name": "HttpInputDataHandler by token",
      "options": {
        "query": "search `exec_health_hec_handler`\n| rex \"token name=(?<token>[^,]+)\"\n| rex \"reply=(?<reply>\\d+)\"\n| eval token=coalesce(token, \"n/a\")\n| eval is_error=if(log_level=\"ERROR\" OR log_level=\"WARN\", 1, 0)\n| stats count as events, sum(is_error) as errors, values(reply) as reply_codes by token\n| lookup hec_token_map token OUTPUT token_name, owner\n| eval token_label=coalesce(token_name, token)\n| eval _color_rank=if(errors>0, 1, 3)\n| table token, token_label, owner, events, errors, reply_codes, _color_rank\n| sort 0 -errors, -events",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_hec_errors": {
      "type": "ds.search",
      "name": "HttpInputDataHandler issues",
      "options": {
        "query": "search `exec_health_hec_handler` (log_level=ERROR OR log_level=WARN)\n| timechart span=5m count as handler_issues",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_hec_alert_count": {
      "type": "ds.chain",
      "name": "HEC alert count",
      "options": {
        "extend": "ds_hec_state",
        "query": "| where hec_state=\"ALERT\" | stats count as alerts"
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# HEC token performance\nThroughput comes from the per-token HEC metrics in `_introspection` (`http_event_collector_metrics`, field `data.token_name`). A token whose previous hour averaged **100+ events/sec** (macro `exec_health_hec_baseline_eps`) and has sent **nothing for the last 5 complete minutes** is **ALERT**. Map token input names to friendly names in `lookups/hec_token_map.csv` \u2014 never put HEC token secrets in that file.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_tokens": {
      "type": "splunk.singlevalue",
      "title": "Active tokens (1h)",
      "dataSources": {
        "primary": "ds_hec_totals"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"tokens\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 0,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_eps": {
      "type": "splunk.singlevalue",
      "title": "HEC events / sec (1h)",
      "dataSources": {
        "primary": "ds_hec_totals"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"events_per_sec\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 1,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_gb": {
      "type": "splunk.singlevalue",
      "title": "HEC volume (1h)",
      "dataSources": {
        "primary": "ds_hec_totals"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"gb\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 3,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "unit": " GB",
        "unitPosition": "after",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_alerts": {
      "type": "splunk.singlevalue",
      "title": "Tokens in ALERT",
      "dataSources": {
        "primary": "ds_hec_alert_count"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"alerts\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 0,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_time": {
      "type": "splunk.area",
      "dataSources": {
        "primary": "ds_hec_time"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "seriesColors": [
          "#58A6FF",
          "#3FB950",
          "#E3B341",
          "#F85149",
          "#A371F7"
        ],
        "legendDisplay": "right",
        "yAxisTitleText": "events / 5m",
        "areaOpacity": 0.35,
        "nullValueDisplay": "connect",
        "backgroundColor": "transparent"
      }
    },
    "viz_state": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_hec_state"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "count": 25,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)",
          "headerBackgroundColor": "transparent",
          "headerColor": "#8B949E"
        },
        "columnFormat": {
          "severity": {
            "rowColors": "> table | seriesByName(\"severity\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"severity\") | matchValue(pillBg)"
          },
          "status": {
            "rowColors": "> table | seriesByName(\"status\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(pillBg)"
          },
          "state": {
